#!/usr/bin/env node
import {
  exportRecipe
} from "./chunk-PS42E7L3.js";
import {
  NUTRITION_BASIS_FLAG_DESCRIPTION,
  parseNutritionBasis
} from "./chunk-CZEB27I3.js";
import {
  resolveScaleArg
} from "./chunk-E4B6DFAN.js";
import {
  resolveStockFromConfig
} from "./chunk-EXIXW6Q5.js";
import "./chunk-JCFG34DV.js";
import "./chunk-XW73TKNN.js";
import "./chunk-4MSISIPG.js";
import {
  reportRejectedIngredients
} from "./chunk-4A6RJKSG.js";
import {
  loadDbSafe
} from "./chunk-J5CTY35W.js";
import {
  loadConfig
} from "./chunk-LYQHWV53.js";
import "./chunk-IWNALT6P.js";
import "./chunk-5APUWLPI.js";
import {
  GramCLIError
} from "./chunk-IXNX2GX7.js";

// src/commands/print.ts
import { defineCommand } from "citty";
import { resolve } from "path";
import { log } from "@clack/prompts";
import chalk from "chalk";

// src/services/printer.ts
import { writeFile } from "fs/promises";
import { tmpdir } from "os";
import { join } from "path";
import { spawn } from "child_process";
async function generatePrintHTML(filePath, db, scaleFactor, rendererOptions) {
  const html = await exportRecipe(
    filePath,
    "html",
    db,
    scaleFactor,
    rendererOptions
  );
  const outPath = join(tmpdir(), `gram_print_${Date.now()}.html`);
  await writeFile(outPath, html, "utf-8");
  return outPath;
}
function openInBrowser(htmlPath) {
  const cmds = {
    darwin: ["open", htmlPath],
    win32: ["cmd", "/c", "start", "", htmlPath],
    linux: ["xdg-open", htmlPath]
  };
  const [cmd, ...args] = cmds[process.platform] ?? ["xdg-open", htmlPath];
  try {
    const child = spawn(cmd, args, { stdio: "ignore", detached: true });
    child.unref();
    return true;
  } catch {
    return false;
  }
}

// src/commands/print.ts
var print_default = defineCommand({
  meta: {
    name: "print",
    description: "Generate a print-ready HTML and open it in the browser"
  },
  args: {
    file: {
      type: "positional",
      required: true,
      description: "Path to a .gram recipe file"
    },
    open: {
      type: "boolean",
      description: "Open the generated HTML in the browser (use --no-open to skip)",
      default: true
    },
    scale: {
      type: "string",
      description: "Scale factor (e.g. 1.5) or reference ingredient (e.g. farine=300g)"
    },
    db: {
      type: "string",
      description: "Path to ingredient database YAML"
    },
    "skip-db": {
      type: "boolean",
      description: "Skip ingredient database",
      default: false
    },
    "step-qty": {
      type: "boolean",
      description: "Show ingredient quantities in step text (pass --no-step-qty to hide; quantities in section mise en place are always shown)",
      default: true
    },
    "bakers-math": {
      type: "boolean",
      description: "Display ingredient quantities as a percentage of a reference ingredient (Baker's Percentage)."
    },
    "bakers-reference": {
      type: "string",
      description: "Force a specific ingredient as the baker's math reference (e.g. flour). Implies --bakers-math"
    },
    "bakers-math-only": {
      type: "boolean",
      description: "Only show the percentages and hide absolute weights."
    },
    nutrition: {
      type: "string",
      description: NUTRITION_BASIS_FLAG_DESCRIPTION
    },
    stock: {
      type: "string",
      description: "Comma-separated @use specifiers already on hand for this print (e.g. @bases/pate.gram,./levain.gram)"
    }
  },
  async run({ args }) {
    const filePath = resolve(args.file);
    const config = await loadConfig();
    const dbResult = args["skip-db"] ? null : await loadDbSafe(config, args.db);
    if (dbResult) reportRejectedIngredients(dbResult.rejected, dbResult.dbPath);
    const db = dbResult?.data ?? null;
    const scaleFactor = await resolveScaleArg(
      args.scale,
      filePath,
      db,
      config.language,
      config.paths
    );
    const bakersReference = args["bakers-reference"] || (args["bakers-math"] ? "" : void 0);
    const bakersMathOnly = args["bakers-math-only"];
    const nutritionBasis = parseNutritionBasis(args.nutrition);
    const stock = resolveStockFromConfig(args.stock, config);
    let htmlPath;
    try {
      htmlPath = await generatePrintHTML(filePath, db, scaleFactor, {
        hideStepQty: !args["step-qty"],
        bakersReference,
        bakersMathOnly,
        nutritionBasis,
        lang: config.language,
        paths: config.paths,
        stock
      });
    } catch (err) {
      if (err instanceof GramCLIError) {
        log.error(err.message);
        process.exit(err.exitCode);
      }
      throw err;
    }
    log.success(`HTML generated: ${chalk.dim(htmlPath)}`);
    if (args.open !== false) {
      const opened = openInBrowser(htmlPath);
      if (opened) {
        log.info("Opening in browser\u2026");
      } else {
        log.warn(
          `Could not open browser automatically. Open the file manually:
${htmlPath}`
        );
      }
    }
  }
});
export {
  print_default as default
};
